const BOOK_NAMES={gen:'창세기',exo:'출애굽기',lev:'레위기',num:'민수기',deu:'신명기',jos:'여호수아',jdg:'사사기',rut:'룻기','1sa':'사무엘상','2sa':'사무엘하','1ki':'열왕기상','2ki':'열왕기하','1ch':'역대상','2ch':'역대하',ezr:'에스라',neh:'느헤미야',est:'에스더',job:'욥기',psa:'시편',pro:'잠언',ecc:'전도서',sng:'아가',isa:'이사야',jer:'예레미야',lam:'예레미야애가',ezk:'에스겔',dan:'다니엘',hos:'호세아',jol:'요엘',amo:'아모스',oba:'오바댜',jnh:'요나',mic:'미가',nam:'나훔',hab:'하박국',zep:'스바냐',hag:'학개',zec:'스가랴',mal:'말라기'};
export function oldTestamentMonologues(n,occurrences){
 const out=[];
 for(const [code,chap,name,verses,lines,emotion] of rows){
  if(n.name!==name||!occurrences.some(p=>p.code===code&&p.chap===chap))continue;
  for(const text of lines)out.push({text,ref:`${BOOK_NAMES[code]} ${chap}:${verses}`,emotion,origin:'authored'});
 }
 return out;
}
